  precision: Int = 6,
  formatOptions: immutable.Map[String, Any] = immutable.Map.empty
) extends BaseTokenizer[Any] {

  def tokenize(value: Any): Token = {
    val (strValue, originalType) = value match {
      case bd: BigDecimal =>
        (f"${bd.toDouble}%.${precision}f", "BigDecimal")
      case d: Double =>
        (f"$d%.${precision}f", "Double")
      case f: Float =>
        (f"${f.toDouble}%.${precision}f", "Float")
      case i: Int =>
        (i.toString, "Int")
      case l: Long =>
        (l.toString, "Long")
      case other =>
        (other.toString, other.getClass.getSimpleName)
    }

    Token(strValue, TokenType.Numeric, immutable.Map("original_type" -> originalType))
