 * Handles LocalDate and LocalDateTime.
 */
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val isoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Any): Token = {
    val formatted = value match {
      case dt: LocalDateTime =>
        val fmt = formatStr.getOrElse(isoFormat.format(dt))
        if (formatStr.isDefined) {
          LocalDateTime.parse(dt.toString, DateTimeFormatter.ofPattern(formatStr.get)).toString
        } else {
          isoFormat.format(dt)
        }
      case ld: LocalDate =>
        val fmt = formatStr.getOrElse(dateFormat.format(ld))
        if (formatStr.isDefined) {
          LocalDate.parse(ld.toString, DateTimeFormatter.ofPattern(formatStr.get)).toString
        } else {
          dateFormat.format(ld)
        }
      case other =>
        other.toString
    }

    Token(formatted, TokenType.Temporal)
  }
