/**
 * Tokenizer that handles multiple types with pattern matching.
 * This is Scala's type-safe alternative to Python's isinstance checks.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null =>
      Token("NULL", TokenType.Null)

    case tokenizable: Tokenizable[_] =>
      Token(tokenizable.toToken(tokenizable.asInstanceOf[Any]), TokenType.Structured)

    case s: String =>
      stringTokenizer.tokenize(s)

    case bytes: Array[Byte] =>
      stringTokenizer.tokenizeBytes(bytes)

    case i: Int =>
      numericTokenizer.tokenize(i)

    case l: Long =>
      numericTokenizer.tokenize(l)

    case d: Double =>
      numericTokenizer.tokenize(d)

    case f: Float =>
      numericTokenizer.tokenize(f)

    case bd: BigDecimal =>
      numericTokenizer.tokenize(bd)

    case dt: LocalDateTime =>
      temporalTokenizer.tokenize(dt)

    case ld: LocalDate =>
      temporalTokenizer.tokenize(ld)

    case other =>
      Token(other.toString, TokenType.String, immutable.Map("fallback" -> true))
  }

  def tokenizeBatch(values: Iterator[Any]): Iterator[Token] =
    values.map(tokenize)
}

