/**
 * Simulated functor for tokens - models mappable values.
 * Scala has more powerful abstractions, but this shows the pattern.
 */
class TokenFunctor[+T](value: T) {
  def map[B](func: T => B): TokenFunctor[B] =
    new TokenFunctor(func(value))

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] =
    func(value)

  def getOrElse[B >: T](default: B): B =
    value match {
      case null => default
      case _ => value
    }

  def get: T = value
}

/**
 * Extended monad operations for tokens.
 */
class TokenMonad[+T](value: T) extends TokenFunctor(value) {
