  def withMetadata(key: String, value: Any): TokenizerBuilder[T] =
    copy(metadata = metadata + (key -> value))

  def withMetadata(moreMetadata: (String, Any)*): TokenizerBuilder[T] =
    copy(metadata = metadata ++ moreMetadata.toMap)

  /**
   * Build the final tokenizer function.
   * Returns a function that can tokenize values.
   */
  def build(): T => Token = { value: T =>
    // Validate
    for (validator <- validators) {
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    for (normalizer <- normalizers) {
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.String, metadata)
  }

  /**
   * Build a function that validates and tokenizes, returning Option[Token].
   */
  def buildSafe(): T => Option[Token] = { value: T =>
    Try {
      // Validate
      for (validator <- validators) {
        if (!validator(value)) {
          return None
        }
      }

      // Convert to string
      var strValue = value.toString

      // Normalize
      for (normalizer <- normalizers) {
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, metadata)
    }.toOption
  }
}

