/**
 * Tokenizer module for converting various input types to standardized tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Generic types with covariant/contravariant variance
 * - Sealed traits for algebraic data types
 * - Pattern matching for type-safe dispatch
 * - Case classes for immutable data structures
 * - Type classes for extensible polymorphism
 * - Option/Either for functional error handling
 */

import java.time.format.DateTimeFormatter
import java.time.{LocalDate, LocalDateTime}
import scala.collection.immutable
import scala.math.BigDecimal
import scala.util.Try

// ============================================================================
// Type Definitions and Enums
// ============================================================================

/**
 * Sealed trait representing the type of a token.
 * Enables exhaustive pattern matching at compile time.
 */
sealed trait TokenType {
  def code: String
}

object TokenType {
  case object String extends TokenType { val code = "string" }
  case object Numeric extends TokenType { val code = "numeric" }
  case object Temporal extends TokenType { val code = "temporal" }
  case object Structured extends TokenType { val code = "structured" }
  case object Binary extends TokenType { val code = "binary" }
  case object Null extends TokenType { val code = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation with value, type, and metadata.
 * Case class provides equals, hashCode, toString, and copy() for free.
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: immutable.Map[String, Any] = immutable.Map.empty
) {
  /**
   * Returns a new token with additional metadata merged in.
   * Immutable operation - does not modify this token.
   */
  def withMetadata(moreMetadata: (String, Any)*): Token =
    copy(metadata = metadata ++ moreMetadata.toMap)
}

/**
 * Mutable batch of tokens for accumulating results.
 * Represents the contrast between immutable Token and mutable batches.
 */
case class MutableTokenBatch(
  tokens: immutable.Vector[Token] = immutable.Vector.empty,
  private val processed: Boolean = false
) {
  def add(token: Token): MutableTokenBatch = {
    if (processed) {
      throw new IllegalStateException("Batch already processed")
    }
    copy(tokens = tokens :+ token)
  }

  def markProcessed: MutableTokenBatch =
    copy(processed = true)

  def isProcessed: Boolean = processed
}

// ============================================================================
// Generic Container Classes (Variance Examples)
// ============================================================================

/**
 * Covariant container - can return subtypes.
 * Type parameter T is covariant (+T) because it only appears in output position.
 */
class TokenContainer[+T](items: immutable.Seq[T]) {
  private val _items: immutable.Vector[T] = items.toVector

  def getAll: immutable.Vector[T] = _items

  def mapTokens[S](func: T => S): immutable.Vector[S] =
    _items.map(func)
}

/**
 * Contravariant sink - can accept supertypes.
 * Type parameter T is contravariant (-T) because it only appears in input position.
 */
class TokenSink[-T] {
  private var _received: immutable.Vector[Any] = immutable.Vector.empty

  def receive(item: T): Unit = {
    _received = _received :+ item
  }

  def drain(): immutable.Vector[Any] = {
    val result = _received
    _received = immutable.Vector.empty
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 * Type parameter T is invariant (no +/-) because it appears in both input and output.
 */
class BivariantHandler[T](initial: T) {
  private var _value: T = initial

  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Type Classes (Scala's approach to extensible polymorphism)
// ============================================================================

/**
 * Type class for types that can be converted to tokens.
 * This replaces Python's Tokenizable protocol with compile-time safety.
 */
trait Tokenizable[T] {
  def toToken(value: T): String
}

object Tokenizable {
  implicit val stringTokenizable: Tokenizable[String] = identity
  implicit val intTokenizable: Tokenizable[Int] = _.toString
  implicit val longTokenizable: Tokenizable[Long] = _.toString
  implicit val doubleTokenizable: Tokenizable[Double] = _.toString
}

// ============================================================================
// Base Tokenizer Hierarchy
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 * Defines the core interface for all tokenizers.
 */
abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values using Iterator.
   * Enables processing of large sequences without loading all into memory.
   */
  def tokenizeBatch(values: Iterator[T]): Iterator[Token] =
    values.map(tokenize)
}

/**
 * Tokenizer for string and bytes types with optional normalization.
 * Handles encoding conversion and text normalization.
 */
class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    val normalized = normalizer(value)
    Token(normalized, TokenType.String)
  }

  def tokenizeBytes(value: Array[Byte]): Token = {
    val str = new String(value, encoding)
    tokenize(str)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 * Handles Int, Long, Double, Float, and BigDecimal.
 */
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: immutable.Map[String, Any] = immutable.Map.empty
) extends BaseTokenizer[Any] {

  def tokenize(value: Any): Token = {
    val (strValue: String, originalType: String) = value match {
      case bd: BigDecimal =>
        val fmt = s"%.${precision}f"
        (fmt.format(bd.toDouble), "BigDecimal")
      case d: Double =>
        val fmt = s"%.${precision}f"
        (fmt.format(d), "Double")
      case f: Float =>
        val fmt = s"%.${precision}f"
        (fmt.format(f.toDouble), "Float")
      case i: Int =>
        (i.toString, "Int")
      case l: Long =>
        (l.toString, "Long")
      case other =>
        (other.toString, other.getClass.getSimpleName)
    }

    Token(strValue, TokenType.Numeric, immutable.Map[String, Any]("original_type" -> originalType))
  }
}

/**
 * Tokenizer for date/time types with configurable formatting.
 * Handles LocalDate and LocalDateTime.
 */
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val isoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Any): Token = {
    val formatted = value match {
      case dt: LocalDateTime =>
        val fmt = formatStr.getOrElse(isoFormat.format(dt))
        if (formatStr.isDefined) {
          LocalDateTime.parse(dt.toString, DateTimeFormatter.ofPattern(formatStr.get)).toString
        } else {
          isoFormat.format(dt)
        }
      case ld: LocalDate =>
        val fmt = formatStr.getOrElse(dateFormat.format(ld))
        if (formatStr.isDefined) {
          LocalDate.parse(ld.toString, DateTimeFormatter.ofPattern(formatStr.get)).toString
        } else {
          dateFormat.format(ld)
        }
      case other =>
        other.toString
    }

    Token(formatted, TokenType.Temporal)
  }
}

// ============================================================================
// Universal Tokenizer (Multi-Type Dispatch)
// ============================================================================

/**
 * Tokenizer that handles multiple types with pattern matching.
 * This is Scala's type-safe alternative to Python's isinstance checks.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null =>
      Token("NULL", TokenType.Null)

    case s: String =>
      stringTokenizer.tokenize(s)

    case bytes: Array[Byte] =>
      stringTokenizer.tokenizeBytes(bytes)

    case i: Int =>
      numericTokenizer.tokenize(i)

    case l: Long =>
      numericTokenizer.tokenize(l)

    case d: Double =>
      numericTokenizer.tokenize(d)

    case f: Float =>
      numericTokenizer.tokenize(f)

    case bd: BigDecimal =>
      numericTokenizer.tokenize(bd)

    case dt: LocalDateTime =>
      temporalTokenizer.tokenize(dt)

    case ld: LocalDate =>
      temporalTokenizer.tokenize(ld)

    case other =>
      Token(other.toString, TokenType.String, immutable.Map[String, Any]("fallback" -> true))
  }

  def tokenizeBatch(values: Iterator[Any]): Iterator[Token] =
    values.map(tokenize)
}

// ============================================================================
// Token Registry (Complex Nested Generics)
// ============================================================================

/**
 * Registry with complex nested generic types for managing containers and handlers.
 * Demonstrates composition of generic types.
 */
class TokenRegistry[T] {
  private var _registry: immutable.Map[String, TokenContainer[T]] =
    immutable.Map.empty

  private var _handlers: immutable.Vector[T => Option[Token]] =
    immutable.Vector.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry = _registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers = _handlers :+ handler
  }

  def process(key: String): immutable.Vector[Option[Token]] = {
    _registry.get(key) match {
      case None => immutable.Vector.empty
      case Some(container) =>
        container.getAll.flatMap { item =>
          _handlers.collectFirst {
            case handler if handler(item).isDefined =>
              handler(item)
          }.orElse(Some(None))
        }
    }
  }
}

// ============================================================================
// Functor and Monad for Tokens
// ============================================================================

/**
 * Simulated functor for tokens - models mappable values.
 * Scala has more powerful abstractions, but this shows the pattern.
 */
class TokenFunctor[+T](value: T) {
  def map[B](func: T => B): TokenFunctor[B] =
    new TokenFunctor(func(value))

  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] =
    func(value)

  def getOrElse[B >: T](default: B): B =
    value match {
      case null => default
      case _ => value
    }

  def get: T = value
}

/**
 * Extended monad operations for tokens.
 */
class TokenMonad[+T](value: T) extends TokenFunctor(value) {
  def ap[A >: T, B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get.asInstanceOf[T => B].apply(value))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Recursive type for JSON values.
 * Sealed trait pattern enables type-safe recursive data structures.
 */
sealed trait JsonValue

object JsonValue {
  case class JsonObject(fields: immutable.Map[String, JsonValue]) extends JsonValue
  case class JsonArray(items: immutable.Vector[JsonValue]) extends JsonValue
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: Double) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonBoolean(value: Boolean) extends JsonValue

  /**
   * Convert to standard Scala types for JSON serialization.
   */
  def toAny(json: JsonValue): Any = json match {
    case JsonObject(fields) => fields.mapValues(toAny)
    case JsonArray(items) => items.map(toAny)
    case JsonString(s) => s
    case JsonNumber(n) => n
    case JsonNull => null
    case JsonBoolean(b) => b
  }
}

/**
 * Tokenizer for JSON structures with recursive type support.
 * Uses play-json or manual serialization depending on availability.
 */
class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) {
      prettyPrintJson(value)
    } else {
      printJson(value)
    }

    Token(jsonStr, TokenType.Structured, immutable.Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    navigateJson(value, parts).map(tokenize)
  }

  private def navigateJson(value: JsonValue, path: List[String]): Option[JsonValue] =
    path match {
      case Nil => Some(value)
      case part :: rest =>
        value match {
          case JsonValue.JsonObject(fields) =>
            fields.get(part).flatMap(navigateJson(_, rest))
          case JsonValue.JsonArray(items) =>
            Try(part.toInt).toOption.flatMap { idx =>
              if (idx >= 0 && idx < items.length) {
                navigateJson(items(idx), rest)
              } else {
                None
              }
            }
          case _ => None
        }
    }

  private def printJson(value: JsonValue): String = value match {
    case JsonValue.JsonObject(fields) =>
      val items = fields.map { case (k, v) => s""""$k":${printJson(v)}""" }
      "{" + items.mkString(",") + "}"
    case JsonValue.JsonArray(items) =>
      "[" + items.map(printJson).mkString(",") + "]"
    case JsonValue.JsonString(s) =>
      s""""$s""""
    case JsonValue.JsonNumber(n) => n.toString
    case JsonValue.JsonNull => "null"
    case JsonValue.JsonBoolean(b) => b.toString
  }

  private def prettyPrintJson(value: JsonValue, indent: Int = 0): String = {
    val indentStr = " " * indent
    val nextIndentStr = " " * (indent + 2)

    value match {
      case JsonValue.JsonObject(fields) if fields.isEmpty => "{}"
      case JsonValue.JsonObject(fields) =>
        val items = fields.map { case (k, v) =>
          s"""$nextIndentStr"$k": ${prettyPrintJson(v, indent + 2)}"""
        }
        "{\n" + items.mkString(",\n") + s"\n$indentStr}"

      case JsonValue.JsonArray(items) if items.isEmpty => "[]"
      case JsonValue.JsonArray(items) =>
        val formatted = items.map(prettyPrintJson(_, indent + 2))
        "[\n" + formatted.map(nextIndentStr + _).mkString(",\n") + s"\n$indentStr]"

      case JsonValue.JsonString(s) => s""""$s""""
      case JsonValue.JsonNumber(n) => n.toString
      case JsonValue.JsonNull => "null"
      case JsonValue.JsonBoolean(b) => b.toString
    }
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * Fundamental operation used in NLP and text processing.
 */
class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] =
    Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  /**
   * Process a single word into a token string.
   * Returns None if the word is filtered out.
   */
  def processToken(word: String): Option[String] = {
    var result = word

    if (stripPunctuation) {
      result = result.filter(!punctuation.contains(_))
    }

    if (lowercase) {
      result = result.toLowerCase
    }

    if (result.length < minLength) {
      None
    } else if (maxLength.exists(result.length > _)) {
      Some(result.take(maxLength.get))
    } else if (result.isEmpty) {
      None
    } else {
      Some(result)
    }
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): immutable.Vector[Token] = {
    val words = text.split("\\s+").toVector
    var position = 0

    words.foldLeft(immutable.Vector.empty[Token]) { (acc, word) =>
      processToken(word) match {
        case Some(processed) =>
          val token = Token(
            processed,
            TokenType.String,
            immutable.Map("position" -> position, "original" -> word)
          )
          position += 1
          acc :+ token
        case None => acc
      }
    }
  }

  /**
   * Split text by whitespace and return just the token strings.
   */
  def tokenizeToStrings(text: String): immutable.Vector[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): immutable.Vector[(String, Int, Int)] = {
    var currentPos = 0
    var result = immutable.Vector.empty[(String, Int, Int)]

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word) match {
        case Some(processed) =>
          result = result :+ (processed, start, end)
        case None => ()
      }

      currentPos = end
    }

    result
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating custom tokenizers.
 * Demonstrates the builder pattern with immutable case classes.
 *
 * Usage:
 * {{{
 *   val tokenize = new TokenizerBuilder[String]()
 *     .withNormalizer(_.toLowerCase)
 *     .withNormalizer(_.trim)
 *     .withMetadata("version", "1.0")
 *     .build()
 * }}}
 */
case class TokenizerBuilder[T](
  normalizers: immutable.Vector[String => String] = immutable.Vector.empty,
  validators: immutable.Vector[T => Boolean] = immutable.Vector.empty,
  metadata: immutable.Map[String, Any] = immutable.Map.empty
) {

  /**
   * Add a normalizer function to the pipeline.
   * Normalizers are applied in order during tokenization.
   */
  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    copy(normalizers = normalizers :+ normalizer)

  /**
   * Add a validator function to the pipeline.
   * All validators must pass (return true) or tokenization fails.
   */
  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    copy(validators = validators :+ validator)

  /**
   * Add metadata to attach to generated tokens.
   */
  def withMetadata(key: String, value: Any): TokenizerBuilder[T] =
    copy(metadata = metadata + (key -> value))

  def withMetadata(moreMetadata: (String, Any)*): TokenizerBuilder[T] =
    copy(metadata = metadata ++ moreMetadata.toMap)

  /**
   * Build the final tokenizer function.
   * Returns a function that can tokenize values.
   */
  def build(): T => Token = { value: T =>
    // Validate
    for (validator <- validators) {
      if (!validator(value)) {
        throw new IllegalArgumentException(s"Validation failed for $value")
      }
    }

    // Convert to string
    var strValue = value.toString

    // Normalize
    for (normalizer <- normalizers) {
      strValue = normalizer(strValue)
    }

    Token(strValue, TokenType.String, metadata)
  }

  /**
   * Build a function that validates and tokenizes, returning Option[Token].
   */
  def buildSafe(): T => Option[Token] = { value: T =>
    Try {
      // Validate
      for (validator <- validators) {
        if (!validator(value)) {
          return None
        }
      }

      // Convert to string
      var strValue = value.toString

      // Normalize
      for (normalizer <- normalizers) {
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.String, metadata)
    }.toOption
  }
}

